  router.get('/api/documents/:id', authenticateToken(true), async (req: Request, res: Response, next: NextFunction) => {
    const { id } = req.params;

    // Check for pending_approval documents (held by workflow gate)
    const pendingDoc = await redisService.getPendingDocument(id) as Record<string, unknown> | null;
    if (pendingDoc) {
      const wfiId = pendingDoc.workflowInstanceId as string;
      const wfi = wfiId ? await redisService.getWorkflowInstance(wfiId) as Record<string, unknown> | null : null;
      res.json({
        id,
        title: pendingDoc.title,
        status: 'pending_approval',
        documentType: pendingDoc.documentType || pendingDoc.type,
        contentHash: pendingDoc.contentHash,
        createdBy: pendingDoc.createdBy,
        createdAt: pendingDoc.createdAt,
        workflowInstance: wfi ? {
          id: wfiId,
          status: wfi.status,
          currentStepIndex: wfi.currentStepIndex,
          steps: wfi.steps,
          workflowName: wfi.workflowName,
        } : undefined,
      });
      return;
    }

    // Check if this document was rejected via workflow
    // Priority: Redis → in-memory Map → DB query
    let rejection: RejectionData | undefined;

    // Try Redis first
    try {
      const redisRejection = await redisService.getRejectedDocument(id);
      if (redisRejection) {
        rejection = {
          status: redisRejection.status,
          rejectionReason: redisRejection.rejectionReason,
          rejectedAt: redisRejection.rejectedAt,
          rejectedBy: redisRejection.rejectedBy,
        };
      }
    } catch { /* Redis unavailable — fall through */ }

    // Fall back to in-memory map
    if (!rejection) {
      rejection = memRejectedDocuments.get(id);
    }

    // Try database if not found in Redis or memory
    if (!rejection && isDbAvailable()) {
      try {
        const result = await query<{
          document_id: string;
          rejected_by: string;
          reason: string;
        }>('SELECT * FROM svc_gateway_rejections WHERE document_id = $1', [id]);

        if (result.rows.length > 0) {
          const row = result.rows[0] as any;
          rejection = {
            status: 'rejected',
            rejectionReason: row.reason,
            rejectedAt: new Date().toISOString(),
            rejectedBy: row.rejected_by,
          };
          memRejectedDocuments.set(id, rejection);
          // Back-fill Redis from DB result (fire-and-forget)
          redisService.setRejectedDocument(id, rejection).catch(() => {});
        }
      } catch (err: any) {
        // Ignore DB errors - fallback to in-memory only
      }
    }

    if (rejection) {
      res.json({
        id,
        status: rejection.status,
        rejectionReason: rejection.rejectionReason,
        rejectedAt: rejection.rejectedAt,
        rejectedBy: rejection.rejectedBy,
        type: 'DEGREE',
        data: {},
      });
      return;
    }

    // Pass through to originate service via proxy
    next();
  });

  // =========================================================================
  // Block sign/anchor/share on documents pending workflow approval
  // =========================================================================

  router.post('/api/documents/:id/sign', authenticateToken(true), blockPendingApproval);
  router.post('/api/documents/:id/sign/request', authenticateToken(true), blockPendingApproval);
  router.post('/api/documents/:id/anchor', authenticateToken(true), blockPendingApproval);
  router.post('/api/documents/:id/share', authenticateToken(true), blockPendingApproval);

  // KS-375: the mock GET /api/notifications that lived here was dead code —
  // routes/notifications.ts is mounted first (index.ts) and always won the
  // route match, so this handler could never run. Removed.

  // ==========================================================================
  // GOVERNANCE — no handlers here (KS-450)
  // ==========================================================================
  // The governance mock that lived here (GET /api/governance/state, GET+POST
  // /api/governance/proposals, POST /api/governance/proposals/{id}/vote) was
  // labelled a "fallback" but was mounted BEFORE the governance proxy, so it
  // ALWAYS shadowed the real service: proposals created through the public API
  // existed only in the mock's memory and could never be listed, submitted,
  // cancelled, executed or voted through the real governance service. Removed
  // in KS-450 — all /api/governance/* traffic now flows through the catch-all
  // proxy in routes/proxy.ts to the governance microservice, which enforces
  // its own JWT auth and the published request schemas (CreateProposalSchema,
  // CastVoteSchema — pinned by that service's unit tests).

  // =========================================================================
  // PUBLIC DOCUMENT TYPES ENDPOINT (no admin auth required)
  // =========================================================================

  router.get('/api/document-types', async (_req: Request, res: Response) => {
    try {
      const allTypes = await redisService.getAllDocumentTypes();
      const active = (allTypes as Array<Record<string, unknown>>)
        .filter(dt => dt.isActive !== false)
        .map(dt => ({
          id: dt.id,
          name: dt.name,
          code: dt.code,
          description: dt.description,
          category: dt.category,
          creatorVerificationLevel: dt.creatorVerificationLevel || 'none',
          ownerVerificationLevel: dt.ownerVerificationLevel || 'none',
          viewerVerificationLevel: dt.viewerVerificationLevel || 'none',
          verifierVerificationLevel: dt.verifierVerificationLevel || 'none',
          requireMFA: dt.requireMFA || false,
          requireWalletSignature: dt.requireWalletSignature || false,
          requireKYC: dt.requireKYC || false,
          allowedAuthProviders: dt.allowedAuthProviders || [],
          requiresApproval: dt.requiresApproval || false,
          metadataSchema: dt.metadataSchema || [],
        }));
      res.json(active);
    } catch (err) {
      res.status(500).json({ success: false, error: { code: 'INTERNAL_ERROR', message: 'Failed to fetch document types' } });
    }
  });

  return router;
}

/**
 * KS-466 §7 — POST /api/documents enforcement failures must use the standard
 * error envelope, and the spec's own DocumentCreateRequest example
 * (documentType: PROPERTY_DEED) must resolve against the seeded catalogue.
 *
 * §7b: the enforcement-failure path in routes/verification.ts was the one
 * response answering the FLAT `{error, code}` shape instead of the
 * `{success:false, error:{code,message}}` envelope every sibling response
 * (and the published spec) uses — a customer replaying the spec's example got
 * both a 400 AND an off-contract error body.
 *
 * §7a: the example's PROPERTY_DEED type was never in SEED_DOCUMENT_TYPES, so
 * copy-pasting the published example earned 400 UNKNOWN_DOCUMENT_TYPE on any
 * seeded env. It is now seeded permissive (DOCUMENT-shaped).
 */

import { describe, it, expect, vi } from 'vitest';
import { EventEmitter } from 'node:events';
import type { Request, Response, NextFunction } from 'express';
import { createVerificationRoutes, type VerificationRouteDeps } from '../routes/verification';
import { SEED_DOCUMENT_TYPES } from '../routes/admin';

// ---------------------------------------------------------------------------
// §7a — seeded catalogue carries the spec example's type, permissively
// ---------------------------------------------------------------------------

describe('KS-466 §7a — PROPERTY_DEED in the seeded document-type catalogue', () => {
  const deed = SEED_DOCUMENT_TYPES.find(
    (dt) => (dt as { code?: string }).code === 'PROPERTY_DEED',
  ) as Record<string, unknown> | undefined;

  it('is seeded (the published DocumentCreateRequest example uses it)', () => {
    expect(deed).toBeDefined();
  });

  it('is active and permissive enough for the example to work copy-paste', () => {
    expect(deed?.isActive).toBe(true);
    expect(deed?.creatorVerificationLevel).toBe('none');
    expect(deed?.requireMFA).toBe(false);
    expect(deed?.requiresApproval).toBe(false);
    expect(deed?.metadataSchema).toEqual([]);
  });
});

// ---------------------------------------------------------------------------
// §7b — enforcement failure renders the standard envelope
// ---------------------------------------------------------------------------

function makeDeps(overrides: Partial<VerificationRouteDeps> = {}): VerificationRouteDeps {
  return {
    authenticateToken: () => (req: Request, _res: Response, next: NextFunction) => {
      req.user = { userId: 'u1', email: 't@secuura.io', role: 'user', verificationLevel: 'standard' } as never;
      next();
    },
    mockBodyParser: (_req, _res, next) => next(),
    query: vi.fn(async () => ({ rows: [] })),
    isDbAvailable: () => false,
    redisService: {} as never,
    services: {},
    log: vi.fn(),
    memWorkflowToDocumentMap: new Map(),
    memRejectedDocuments: new Map(),
    dbSaveRejection: vi.fn(async () => undefined),
    ADMIN_ROLES: ['OWNER', 'ISSUER_ADMIN'],
    enforceDocumentTypeRules: vi.fn(async () => ({
      ok: false as const,
      status: 400,
      error: 'Unknown document type "PROPERTY_DEED" — not in the registered document-type catalogue (see GET /api/document-types)',
      code: 'UNKNOWN_DOCUMENT_TYPE',
    })),
    createWorkflowInstanceIfRequired: vi.fn(async () => ({ gated: false as const })),
    meetsVerificationLevel: () => true,
    ...overrides,
  };
}

/** Dispatch POST /api/documents through the real router with a raw-stream req double. */
function dispatchCreate(deps: VerificationRouteDeps, body: unknown): Promise<{ status: number; body: any }> {
  const router = createVerificationRoutes(deps);
  return new Promise((resolve, reject) => {
    const req: any = new EventEmitter();
    Object.assign(req, {
      method: 'POST',
      url: '/api/documents',
      baseUrl: '',
      originalUrl: '/api/documents',
      headers: { 'content-type': 'application/json' },
    });
    const res: any = {
      statusCode: 200,
      status(code: number) {
        this.statusCode = code;
        return this;
      },
      json(payload: unknown) {
        resolve({ status: this.statusCode, body: payload });
        return this;
      },
    };
    (router as unknown as (rq: any, rs: any, nx: (e?: unknown) => void) => void)(
      req,
      res,
      (err?: unknown) => reject(err ?? new Error('route did not match POST /api/documents')),
    );
    // The handler consumes the raw stream — emit after dispatch.
    setImmediate(() => {
      req.emit('data', Buffer.from(JSON.stringify(body)));
      req.emit('end');
    });
  });
}

describe('KS-466 §7b — enforcement failure envelope on POST /api/documents', () => {
  it('renders {success:false, error:{code,message}} — not the flat {error, code}', async () => {
    const { status, body } = await dispatchCreate(makeDeps(), {
      title: 'Property Deed — 42 Plinth Lane',
      documentType: 'PROPERTY_DEED',
    });
    expect(status).toBe(400);
    expect(body.success).toBe(false);
    expect(body.error.code).toBe('UNKNOWN_DOCUMENT_TYPE');
    expect(body.error.message).toContain('Unknown document type');
    // The flat legacy keys must be gone.
    expect(body.code).toBeUndefined();
    expect(typeof body.error).not.toBe('string');
  });

  it('envelopes non-400 enforcement failures too (403 verification level)', async () => {
    const deps = makeDeps({
      enforceDocumentTypeRules: vi.fn(async () => ({
        ok: false as const,
        status: 403,
        error: 'This document type requires ENHANCED verification. Your current level is STANDARD.',
        code: 'INSUFFICIENT_VERIFICATION_LEVEL',
      })),
    });
    const { status, body } = await dispatchCreate(deps, { title: 'Degree', documentType: 'DEGREE' });
    expect(status).toBe(403);
    expect(body.success).toBe(false);
    expect(body.error.code).toBe('INSUFFICIENT_VERIFICATION_LEVEL');
    expect(body.error.message).toContain('ENHANCED');
  });
});

// =============================================================================
// KS-1073 — the verify handler's legacy statusless-blob carve-out must NOT apply to tier-2 blobs
// =============================================================================
//
// Tier-2 is anchoring's `/api/anchors/document/:id`, synthesised by
// `makeFetchDocFromAnchorStore`. Every such blob carries `_source: 'anchor_store'` at doc-level.
// The gateway's `persistedAnchored` predicate used to treat ANY statusless blob like `'confirmed'`;
// that carve-out exists for TIER-1 seeded demo documents only. A tier-2 row with no `status` key
// would otherwise report on-chain through the third-party verifier path.
//
// This file reuses the stub originate server, the stub anchor store, and the gateway app from
// ks1057-verify-confidence-is-status-aware.test.ts — same shape, new cells. All original `it(...)`s
// dropped; three cells written below.
// =============================================================================

import { describe, it, expect, beforeAll, afterAll, vi } from 'vitest';
import express from 'express';
import http from 'node:http';
import type { Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import type { RequestHandler } from 'express';

const REAL_TX = 'a'.repeat(64);
const DOC_ID = 'doc-ks1073';
const CONTENT_HASH = 'b'.repeat(64);

let gateway: Server;
let originate: Server;
let gatewayPort: number;
const realFetch = globalThis.fetch;

/** The blockchain blob the stub originate serves for the current cell. */
let currentBlob: Record<string, unknown> | undefined;
/** The anchoring chain-scan reply for the current cell. `null` = no live hit. */
let liveAnchorReply: Record<string, unknown> | null = null;
/** Tier-2 rows served by the stub anchor store. `null` = tier 2 has nothing. */
let anchorStoreRows: Array<Record<string, unknown>> | null = null;
/** When true the stub originate 404s, so the lookup falls through to tier 2. */
let tier1Absent = false;
const jsonHead = { 'Content-Type': 'application/json' };

beforeAll(async () => {
  // Stub originate: the first lookup tier. Serves the document whose blockchain
  // blob each cell sets.
  originate = http.createServer((req, res) => {
    if (req.url === `/api/anchors/document/${DOC_ID}`) {
      if (!anchorStoreRows) { res.writeHead(404, jsonHead); res.end('{}'); return; }
      res.writeHead(200, jsonHead);
      res.end(JSON.stringify({ data: { anchors: anchorStoreRows } }));
      return;
    }
    if (req.url === `/api/documents/${DOC_ID}`) {
      if (tier1Absent) { res.writeHead(404, jsonHead); res.end('{}'); return; }
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        id: DOC_ID,
        status: 'anchored',
        contentHash: CONTENT_HASH,
        owner: { id: 'org-1' },
        ...(currentBlob ? { blockchain: currentBlob } : {}),
      }));
      return;
    }
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end('{}');
  });
  originate.listen(0, '127.0.0.1');
  await new Promise<void>((r) => originate.once('listening', () => r()));
  const originatePort = (originate.address() as AddressInfo).port;

  globalThis.fetch = (async () => (
    liveAnchorReply
      ? { ok: true, status: 200, json: async () => liveAnchorReply, text: async () => '' }
      : { ok: false, status: 404, json: async () => ({}), text: async () => '' }
  )) as never;

  const { createVerificationRoutes } = await import('../routes/verification');
  const mockBodyParser: RequestHandler = express.json({ limit: '1mb' });

  const app = express();
  app.use(
    createVerificationRoutes({
      authenticateToken: () => (req, _res, next) => {
        (req as { user?: unknown }).user = {
          userId: 'u1', email: 'u@secuura.local', role: 'ADMIN',
          organizationId: 'org-1', tenantId: 't1', verificationLevel: 'FULL',
        };
        next();
      },
      mockBodyParser,
      query: vi.fn(async () => ({ rows: [] })) as never,
      isDbAvailable: () => false,
      redisService: {
        getPendingDocument: vi.fn(async () => null),
        deletePendingDocument: vi.fn(async () => undefined),
        getAllDocumentTypes: vi.fn(async () => []),
        getAllWorkflowInstances: vi.fn(async () => []),
        getNotificationSettings: vi.fn(async () => ({})),
        getRejectedDocument: vi.fn(async () => null),
        setRejectedDocument: vi.fn(async () => undefined),
        getWorkflowDocumentMapping: vi.fn(async () => null),
        getWorkflowInstance: vi.fn(async () => null),
        setWorkflowInstance: vi.fn(async () => undefined),
      } as never,
      services: { originate: { url: `http://127.0.0.1:${originatePort}` }, anchoring: { url: `http://127.0.0.1:${originatePort}` } } as never,
      log: () => undefined,
      memWorkflowToDocumentMap: new Map(),
      memRejectedDocuments: new Map(),
      dbSaveRejection: vi.fn(async () => undefined),
      ADMIN_ROLES: ['ADMIN', 'admin'],
      enforceDocumentTypeRules: vi.fn(async () => ({ ok: true, docType: {} })) as never,
      createWorkflowInstanceIfRequired: vi.fn(async () => ({ gated: false })) as never,
      meetsVerificationLevel: () => true,
    }),
  );

  gateway = app.listen(0, '127.0.0.1');
  await new Promise<void>((r) => gateway.once('listening', () => r()));
  gatewayPort = (gateway.address() as AddressInfo).port;
});

afterAll(async () => {
  globalThis.fetch = realFetch;
  await new Promise<void>((r) => gateway.close(() => r()));
  await new Promise<void>((r) => originate.close(() => r()));
});

/** Drive the tier-1 route and return the parsed body. */
async function verify(blob: Record<string, unknown> | undefined): Promise<any> {
  currentBlob = blob;
  liveAnchorReply = null;
  anchorStoreRows = null;
  tier1Absent = false;
  const r = await realFetch(`http://127.0.0.1:${gatewayPort}/api/documents/${DOC_ID}/verify`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer t' },
    body: JSON.stringify({ purpose: 'test' }),
  });
  expect(r.status).toBe(200);
  return r.json();
}

/** Drive the tier-2 path and return the parsed body. */
async function verifyViaAnchorStore(row: Record<string, unknown>): Promise<any> {
  currentBlob = undefined;
  liveAnchorReply = null;
  tier1Absent = true;                       // tier 1 misses -> fall through to tier 2
  anchorStoreRows = [{ contentHash: CONTENT_HASH, ...row }];
  const r = await realFetch(`http://127.0.0.1:${gatewayPort}/api/documents/${DOC_ID}/verify`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: 'Bearer t' },
    body: JSON.stringify({ purpose: 'test' }),
  });
  expect(r.status).toBe(200);
  const body = await r.json();
  // Guard the whole family: if tier 2 were not the tier that answered, every assertion below would be about the wrong code path.
  expect(body.blockchain.source).toBe('persisted');
  return body;
}

describe('KS-1073 — a statusless tier-2 row is NOT anchored (carve-out is tier-1 only)', () => {
  it('🔴 KS-1073 — a tier-2 anchor-store row with NO status is not anchored', async () => {
    const body = await verifyViaAnchorStore({ transactionHash: REAL_TX, blockNumber: 4242 });
    expect(body.verified).toBe(false);
    expect(body.verificationConfidence).toBe('off-chain-only');
  });

  it('🔴 KS-1073 — the same statusless tier-2 row reports blockchain.anchored false', async () => {
    const body = await verifyViaAnchorStore({ transactionHash: REAL_TX, blockNumber: 4242 });
    expect(body.blockchain.anchored).toBe(false);
  });

  it('KS-1073 control — a tier-1 legacy statusless blob still reports on-chain, and a CONFIRMED tier-2 row still does', async () => {
    // Tier-1 legacy cell must stay green before AND after the fix.
    let body = await verify({
      txHash: '8f3b2c1a4e5d6f7089ab1cd2ef3456789012abcdef3456789012abcdef345678',
      blockHeight: 1024576,
      anchoredAt: new Date().toISOString(),
    });
    expect(body.verified).toBe(true);
    expect(body.verificationConfidence).toBe('on-chain');

    // Confirmed tier-2 row must also stay green before AND after the fix.
    body = await verifyViaAnchorStore({ transactionHash: REAL_TX, blockNumber: 4242, status: 'confirmed' });
    expect(body.verified).toBe(true);
    expect(body.verificationConfidence).toBe('on-chain');
  });
});
